#!/usr/bin/env node
/**
 * Patch a Capacitor Android project generated by `cap add android`.
 *
 *   node scripts/prepare-android.mjs
 *
 * The android/ tree is gitignored and created in CI, the same way ios/ is.
 * This locks both landscape orientations, lets the WebView use the display
 * cutout, hides the status and gesture bars, stamps versionCode from
 * GITHUB_RUN_NUMBER, and signs release when ANDROID_KEYSTORE_PATH is set.
 * The application id is capacitor.config.ts appId, io.knyazev.lighterthanair,
 * the same id iOS uses.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));

const ACTIVITY = 'android:name=".MainActivity"';
const LANDSCAPE = `${ACTIVITY}\n            android:screenOrientation="sensorLandscape"`;
const CUTOUT = '        <item name="android:windowLayoutInDisplayCutoutMode">shortEdges</item>\n';

function mustReplace(file, text, from, to) {
  if (text.includes(to)) return text;
  if (!text.includes(from)) {
    throw new Error(`${file} is missing ${JSON.stringify(from)}`);
  }
  return text.replace(from, to);
}

/**
 * @param {string} androidDir
 * @param {{ versionCode: number, versionName: string, keystorePath?: string }} options
 */
export function prepareAndroid(androidDir, options) {
  const { versionCode, versionName, keystorePath = "" } = options;
  if (!Number.isInteger(versionCode) || versionCode < 1) {
    throw new Error(`versionCode must be a positive integer, got ${versionCode}`);
  }
  if (!versionName) throw new Error("versionName is required");

  const manifestPath = join(androidDir, "app/src/main/AndroidManifest.xml");
  const manifest = readFileSync(manifestPath, "utf8");
  if (!manifest.includes("sensorLandscape")) {
    writeFileSync(manifestPath, mustReplace(manifestPath, manifest, ACTIVITY, LANDSCAPE));
  }

  const stylesPath = join(androidDir, "app/src/main/res/values/styles.xml");
  let styles = readFileSync(stylesPath, "utf8");
  if (!styles.includes("windowLayoutInDisplayCutoutMode")) {
    styles = mustReplace(
      stylesPath,
      styles,
      '        <item name="android:background">@null</item>\n',
      '        <item name="android:background">@null</item>\n' + CUTOUT,
    );
    styles = mustReplace(
      stylesPath,
      styles,
      '        <item name="android:background">@drawable/splash</item>\n',
      '        <item name="android:background">@drawable/splash</item>\n' + CUTOUT,
    );
    writeFileSync(stylesPath, styles);
  }

  const configPath = join(androidDir, "app/src/main/assets/capacitor.config.json");
  const config = JSON.parse(readFileSync(configPath, "utf8"));
  config.plugins ??= {};
  config.plugins.SystemBars = {
    ...config.plugins.SystemBars,
    hidden: true,
    insetsHandling: "css",
    // DARK means light icons on a dark background, for when a swipe reveals the bars.
    style: "DARK",
    animation: "NONE",
  };
  writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`);

  const gradlePath = join(androidDir, "app/build.gradle");
  let gradle = readFileSync(gradlePath, "utf8");
  gradle = gradle.replace(/versionCode \d+/, `versionCode ${versionCode}`);
  gradle = gradle.replace(/versionName "[^"]*"/, `versionName "${versionName}"`);
  if (keystorePath && !gradle.includes("signingConfigs")) {
    gradle = mustReplace(
      gradlePath,
      gradle,
      "android {\n",
      `android {
    signingConfigs {
        release {
            storeFile file(System.getenv("ANDROID_KEYSTORE_PATH"))
            storePassword System.getenv("ANDROID_KEYSTORE_PASSWORD")
            keyAlias System.getenv("ANDROID_KEY_ALIAS")
            keyPassword System.getenv("ANDROID_KEY_PASSWORD")
        }
    }
`,
    );
    gradle = mustReplace(
      gradlePath,
      gradle,
      "minifyEnabled false\n",
      "minifyEnabled false\n            signingConfig signingConfigs.release\n",
    );
  }
  if (!new RegExp(`versionCode ${versionCode}\\b`).test(gradle)) {
    throw new Error(`${gradlePath} has no versionCode ${versionCode}`);
  }
  if (!gradle.includes(`versionName "${versionName}"`)) {
    throw new Error(`${gradlePath} has no versionName "${versionName}"`);
  }
  writeFileSync(gradlePath, gradle);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const versionCode = Number(process.env.GITHUB_RUN_NUMBER || "1");
  try {
    prepareAndroid(join(ROOT, "android"), {
      versionCode,
      versionName: `1.0.${versionCode}`,
      keystorePath: process.env.ANDROID_KEYSTORE_PATH || "",
    });
  } catch (err) {
    console.error(`[prepare-android] ${err?.message || err}`);
    process.exit(1);
  }
  console.log(`[prepare-android] version 1.0.${versionCode}`);
}
